import assert from 'node:assert/strict';
import { slugify } from '../src/slugify.js';

const mode = process.argv[2];
let checked = 0;
let failures = 0;
function check(input, expected) {
  checked++;
  try { assert.equal(slugify(input), expected); }
  catch (error) {
    failures++;
    if (failures <= 15) console.error(JSON.stringify(input), 'expected', JSON.stringify(expected), 'got', error.actual);
  }
}

if (mode === 'examples') {
  for (const [input, expected] of [
    ['Crème Brûlée', 'creme-brulee'], ['Łódź', 'lodz'],
    ['Smørrebrød Æsir Straße', 'smorrebrod-aesir-strasse'],
    ['Cre\u0300me Bru\u0302le\u0301e', 'creme-brulee'],
    ['--Crème / Łódź 2026!--', 'creme-lodz-2026'],
  ]) check(input, expected);
} else if (mode === 'latin') {
  // Every canonically decomposable Latin letter whose base is ASCII,
  // including the Vietnamese, extended Latin and polytonic accent combinations.
  for (let cp = 0; cp <= 0x2fff; cp++) {
    const letter = String.fromCodePoint(cp);
    const decomposed = letter.normalize('NFD');
    if (/^\p{Script=Latin}$/u.test(letter) && /^[A-Za-z]\p{M}+$/u.test(decomposed)) {
      const expected = 'x' + decomposed[0].toLowerCase() + 'y';
      check('X' + letter + 'Y', expected);
      check('X' + decomposed + 'Y', expected);
    }
  }
  // These letters do not become ASCII merely by canonical decomposition.
  for (const [letters, ascii] of [
    ['øØ', 'o'], ['łŁ', 'l'], ['đĐ', 'd'], ['ðÐ', 'd'],
    ['þÞ', 'th'], ['æÆ', 'ae'], ['œŒ', 'oe'], ['ßẞ', 'ss'],
    ['ħĦ', 'h'], ['ı', 'i'], ['ſ', 's'], ['ƒƑ', 'f'],
    ['ǿǾ', 'o'], ['ǽǼ', 'ae'], ['ǣǢ', 'ae'], ['ẛ', 's'],
  ]) {
    for (const letter of letters) {
      check('A' + letter + 'Z', 'a' + ascii + 'z');
      check('A' + letter.normalize('NFD') + 'Z', 'a' + ascii + 'z');
      check('A' + letter + '\u0301\u0327Z', 'a' + ascii + 'z');
    }
  }
  for (const mark of ['\u0300', '\u0301', '\u0308', '\u0327', '\u0304', '\u030a', '\u030b', '\u0331', '\u1ab0', '\u1dc0', '\ufe20']) {
    check('Cafe' + mark + ' noir', 'cafe-noir');
    check('A' + mark + '\u0301B', 'ab');
  }
  check('ÀÉÎÕÜ ÇÑ ŽŠ ŐŰ ĂÂÊÔƠƯ ẮẶỆỘỨỴ', 'aeiou-cn-zs-ou-aaeoou-aaeouy');
  check('Crème Ελληνικά Łódź Й Ё 日本語 Æsir', 'creme-ελληνικά-lodz-й-ё-日本語-aesir');
} else if (mode === 'existing') {
  for (const [input, expected] of [
    ['Hello, World!', 'hello-world'], ['  --Release 2.0--  ', 'release-2-0'],
    ['', ''], [' --- !!! 😀 ', ''], ['A___B...C / D\nE\tF', 'a-b-c-d-e-f'],
    ['ABC123 0 456', 'abc123-0-456'], ['a😀b', 'a-b'],
    ['Привет мир', 'привет-мир'], ['Й Ё й ё Ї ЇЖАК', 'й-ё-й-ё-ї-їжак'],
    ['Αθήνα Ελληνικά Ώ ΐ ΰ ς', 'αθήνα-ελληνικά-ώ-ΐ-ΰ-ς'],
    ['日本語 東京 カタカナ が パ', '日本語-東京-カタカナ-が-パ'],
    ['한국어 한글', '한국어-한글'], ['中文 汉字', '中文-汉字'],
    ['العربية فارسی اردو', 'العربية-فارسی-اردو'], ['שלום עולם', 'שלום-עולם'],
    ['हिन्दी বাংলা தமிழ் ไทย', 'ह-न-द-ব-ল-தம-ழ-ไทย'],
    ['ԱԲԳ ქართული', 'աբգ-ქართული'], ['１２３ ١٢٣ Ⅳ', '１２３-١٢٣-ⅳ'],
    ['a+b=c@d#e', 'a-b-c-d-e'],
  ]) check(input, expected);
  // Script letters must not be transliterated, normalized, or stripped of
  // their precomposed distinctions. Test them individually to avoid boundaries.
  const scripts = /^(?:\p{Script=Cyrillic}|\p{Script=Greek}|\p{Script=Hebrew}|\p{Script=Arabic}|\p{Script=Hiragana}|\p{Script=Katakana}|\p{Script=Hangul})$/u;
  for (let cp = 0; cp <= 0xffff; cp++) {
    const letter = String.fromCodePoint(cp);
    if (/^\p{L}$/u.test(letter) && scripts.test(letter)) {
      check('Q' + letter + 'Z', 'q' + letter.toLowerCase() + 'z');
    }
  }
} else {
  throw new Error('Unknown check mode: ' + mode);
}
console.log(`${checked} cases checked; ${failures} failures`);
if (failures) process.exitCode = 1;
